-- Create the standalone Seha database schema (leaves, users, secrets)
CREATE TABLE sick_leaves (
  id BIGSERIAL PRIMARY KEY,
  record_id TEXT UNIQUE NOT NULL,
  patient_id TEXT NOT NULL DEFAULT '',
  service_code TEXT NOT NULL DEFAULT '',
  is_companion BOOLEAN NOT NULL DEFAULT FALSE,
  data JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_sick_leaves_patient_id ON sick_leaves(patient_id);
CREATE INDEX idx_sick_leaves_service_code ON sick_leaves(service_code);
CREATE INDEX idx_sick_leaves_is_companion ON sick_leaves(is_companion);

CREATE TABLE users (
  username TEXT PRIMARY KEY,
  name TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT 'admin',
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE app_secrets (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

